INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um homem de 62 anos, com antecedente de insuficiência cardíaca congestiva em uso otimizado de furosemida, apresenta-se com dispneia progressiva. A radiografia de tórax revela derrame pleural bilateral, maior à direita. Realizada toracentese diagnóstica que evidencia: Proteína pleural / Proteína sérica = 0,55; LDH pleural / LDH sérica = 0,72; LDH pleural = 240 U/L (Limite superior do soro = 300 U/L). O gradiente de albumina (Soro - Pleura) é de 1,4 g/dL. Diante desses achados, a interpretação correta do líquido pleural e a conduta mais adequada são:", "options": {"a": "Exsudato pelos critérios de Light; iniciar investigação para neoplasia oculta.", "b": "Transudato mascarado pelo uso de diuréticos; manter tratamento da patologia de base.", "c": "Exsudato falso-positivo; realizar biópsia pleural por agulha imediatamente.", "d": "Empiema em fase inicial; iniciar antibioticoterapia de amplo espectro venosa.", "e": "Quilotórax incipiente; solicitar dosagem de triglicerídeos no líquido pleural."}, "answer": "b", "rationale": "O paciente apresenta critérios de Light que sugerem exsudato (LDH pleural/sérica > 0,6), porém o contexto clínico de ICC em uso de diuréticos frequentemente causa exsudatos falso-positivos por concentração de proteínas e LDH. O gradiente de albumina soro-pleura > 1,2 g/dL confirma que o líquido é, na verdade, um transudato. A conduta correta é focar no tratamento da doença de base (ICC).", "option_rationales": {"a": "Incorreta. Embora preencha critérios de Light, o gradiente de albumina desmascara o transudato por diuréticos.", "b": "Correta. O gradiente de albumina soro-pleura > 1,2 g/dL é o padrão-ouro para identificar transudatos em pacientes usando diuréticos.", "c": "Incorreta. A biópsia não é indicada para transudatos de origem cardíaca.", "d": "Incorreta. Não há sinais clínicos ou laboratoriais (como febre ou leucocitose) que sugiram empiema.", "e": "Incorreta. O aspecto do líquido e a clínica não sugerem o acúmulo de linfa (quilotórax)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Critérios de Light", "ICC"]}'::jsonb, 0, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 28 anos, apresenta quadro de tosse seca e dor pleurítica à direita há 15 dias, acompanhada de febre baixa vespertina. O RX de tórax mostra derrame pleural ocupando um terço do hemitórax direito. A análise do líquido pleural revela: Predomínio de linfócitos (85%), glicose de 72 mg/dL, ADA (Adenosina deaminase) de 65 U/L. Não foram visualizados germes no Gram ou BAAR no sedimento. Assinale a alternativa que apresenta o diagnóstico mais provável e o próximo passo recomendado.", "options": {"a": "Mesotelioma maligno; solicitar citologia oncótica e marcadores imuno-histoquímicos.", "b": "Pneumonia bacteriana atípica; iniciar claritromicina e repetir RX em 48 horas.", "c": "Tuberculose pleural; iniciar esquema RIPE conforme diretrizes nacionais.", "d": "Lúpus Eritematoso Sistêmico; dosar anticorpos antinucleares (FAN) no líquido pleural.", "e": "Derrame parapneumônico simples; realizar nova toracentese para drenagem de alívio."}, "answer": "c", "rationale": "Em áreas endêmicas como o Brasil, um líquido pleural exsudativo com predomínio linfocítico e ADA elevado (> 40-60 U/L) tem altíssimo valor preditivo positivo para Tuberculose Pleural, especialmente em pacientes jovens com sintomas subagudos. O diagnóstico pode ser presumido com base nesses achados, permitindo o início do tratamento (esquema RIPE).", "option_rationales": {"a": "Incorreta. Muito improvável pela idade da paciente e pelo valor de ADA.", "b": "Incorreta. Pneumonias atípicas raramente causam derrames com esse perfil citológico e bioquímico.", "c": "Correta. O binômio linfocitose + ADA alto é fortemente sugestivo de TB pleural no Brasil.", "d": "Incorreta. O LES costuma apresentar ADA mais baixo e outros sintomas sistêmicos (artralgia, rash).", "e": "Incorreta. O perfil do líquido (linfocítico) afasta o diagnóstico de exsudato neutrofílico parapneumônico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Tuberculose", "ADA"]}'::jsonb, 1, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos é diagnosticado com derrame pleural parapneumônico. Durante a toracentese diagnóstica, observa-se líquido turvo, pH de 7,12, glicose de 35 mg/dL e LDH de 1200 U/L. A coloração de Gram foi negativa para microrganismos. Com base nas recomendações atuais de manejo da pleura, a melhor conduta imediata para este paciente é:", "options": {"a": "Apenas antibioticoterapia venosa, postergando a drenagem devido ao Gram negativo.", "b": "Toracostomia com drenagem pleural tubular em selo d''água.", "c": "Pleurodese química com talco para evitar a recorrência do derrame.", "d": "Encaminhamento imediato para decorticação pulmonar por toracotomia.", "e": "Realização de toracocinese de alívio repetida a cada 24 horas."}, "answer": "b", "rationale": "Achados de pH < 7,20, glicose < 40-60 mg/dL ou LDH > 1000 U/L em um derrame parapneumônico indicam um exsudato ''complicado'', mesmo com Gram negativo. Nesses casos, a drenagem pleural imediata é mandatória para evitar a evolução para empiema organizado e encarceramento pulmonar.", "option_rationales": {"a": "Incorreta. O pH baixo e a glicose consumida exigem drenagem, independentemente do Gram.", "b": "Correta. Critérios bioquímicos de complicação (pH < 7,2 e glicose baixa) indicam drenagem tubular.", "c": "Incorreta. A pleurodese é contraindicada em infecções pleurais agudas.", "d": "Incorreta. A decorticação é uma medida tardia para casos organizados onde a drenagem falhou.", "e": "Incorreta. Toracocenteses repetidas não são eficazes para derrames parapneumônicos complicados."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural Complicado", "Conduta", "Drenagem"]}'::jsonb, 2, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ocorrência de derrame pleural com característica de exsudato, em paciente com história de febre, emagrecimento, dor torácica e achado de amilase pleural elevada (maior que o limite superior da amilase sérica), direciona o raciocínio clínico prioritariamente para os seguintes diferenciais, EXCETO:", "options": {"a": "Ruptura esofágica (Síndrome de Boerhaave).", "b": "Pancreatite aguda ou crônica (pseudoqueisto pancreático).", "c": "Neoplasia de pulmão ou ovário (adenocarcinoma).", "d": "Tuberculose pleural em fase inicial.", "e": "Adenocarcinoma de pâncreas com metástase pleural."}, "answer": "d", "rationale": "A amilase pleural elevada é encontrada tipicamente em quatro condições: doenças pancreáticas, ruptura esofágica (salivar), neoplasias (amilase isoforma salivar) e, raramente, gravidez ectópica rota. A tuberculose pleural, embora cause exsudato linfocítico, classicamente não cursa com elevação de amilase no líquido pleural.", "option_rationales": {"a": "Incorreta. Ruptura esofágica cursa com amilase muito alta (origem salivar).", "b": "Incorreta. Pancreatite é uma causa clássica de derrame com amilase alta.", "c": "Incorreta. Cerca de 10% das neoplasias malignas pleurais podem elevar a amilase.", "d": "Correta. A Tuberculose Pleural não está associada à elevação de amilase pleural.", "e": "Incorreta. Metástases de adenocarcinoma pancreático seguem a lógica de doenças pancreáticas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Amilase Pleural", "Diagnóstico Diferencial"]}'::jsonb, 3, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Considere um paciente com Cirrose Hepática e ascite volumosa que desenvolve derrame pleural à direita (Hidrotórax Hepático). Sobre esta condição, assinale a afirmativa correta.", "options": {"a": "O mecanismo fisiopatológico principal é a hipoalbuminemia severa isolada.", "b": "A toracentese repetida é o tratamento de escolha a longo prazo.", "c": "A drenagem por tubo de tórax é frequentemente contraindicada devido ao risco de depleção proteica e eletrolítica massiva.", "d": "O líquido pleural costuma ser um exsudato devido à translocação bacteriana.", "e": "A pleurodese química tem alta taxa de sucesso mesmo na presença de ascite descontrolada."}, "answer": "c", "rationale": "No hidrotórax hepático, a drenagem pleural com dreno tubular deve ser evitada ao máximo, pois o líquido pleural é contínuo com a ascite através de defeitos diafragmáticos. A drenagem leva à perda rápida de proteínas, eletrólitos e fluidos, podendo causar insuficiência renal aguda e desnutrição severa.", "option_rationales": {"a": "Incorreta. O mecanismo principal é a passagem de ascite pelos poros diafragmáticos por pressão negativa intratorácica.", "b": "Incorreta. Toracocenteses repetidas aumentam o risco de infecção e empiema.", "c": "Correta. Drenagem tubular em cirróticos com ascite é perigosa e deve ser evitada.", "d": "Incorreta. O líquido é classicamente um transudato.", "e": "Incorreta. A ascite dificulta a sínfise das pleuras, tornando a pleurodese ineficaz."}, "difficulty": "dificil", "tags": ["Pneumologia", "Gastroenterologia", "Hidrotórax Hepático", "Cirrose"]}'::jsonb, 4, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 70 anos, tabagista inveterado, apresenta derrame pleural volumoso à esquerda. A toracentese revela líquido hemorrágico (Hto pleural / Hto periférico = 15%). A citologia oncótica é negativa em duas amostras. O pulmão não expande completamente após a drenagem esvaziadora (pulmão encarcerado). Qual a conduta recomendada para paliação do sintoma de dispneia neste caso?", "options": {"a": "Realizar pleurodese química com talco via dreno de tórax.", "b": "Inserção de cateter pleural de demora (PleurX ou similar).", "c": "Pleurectomia parietal por videotoracoscopia (VATS).", "d": "Encaminhamento para radioterapia de pleura.", "e": "Toracocenteses de alívio mensais conforme a dispneia."}, "answer": "b", "rationale": "O ''pulmão encarcerado'' (trapped lung) ocorre quando a pleura visceral está espessada e impede a expansão pulmonar. Nesses casos, a pleurodese falha porque não há contato entre as pleuras. O cateter pleural de demora é a melhor opção paliativa, permitindo a drenagem domiciliar conforme a necessidade do paciente.", "option_rationales": {"a": "Incorreta. A pleurodese exige reexpansão pulmonar completa para funcionar.", "b": "Correta. O cateter de demora é indicado especificamente para pulmão encarcerado neoplásico.", "c": "Incorreta. A pleurectomia é uma cirurgia de grande porte, raramente indicada para paliação em idosos com doença avançada.", "d": "Incorreta. A radioterapia não é tratamento para derrame pleural volumoso.", "e": "Incorreta. Toracocenteses de repetição causam desconforto e risco de infecção maior que o cateter."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Derrame Pleural Maligno", "Pulmão Encarcerado"]}'::jsonb, 5, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um recém-nascido submetido à cirurgia de correção de cardiopatia congênita desenvolve derrame pleural volumoso no 5º dia pós-operatório. O líquido tem aspecto leitoso, TG = 150 mg/dL e presença de quilomícrons na eletroforese. Sobre o manejo inicial do Quilotórax, assinale a alternativa correta.", "options": {"a": "Drenagem pleural e dieta rica em triglicerídeos de cadeia longa (TCL).", "b": "Uso de octreotide e dieta com triglicerídeos de cadeia média (TCM) ou jejum/NPP.", "c": "Ligadura imediata do ducto torácico por toracotomia nas primeiras 24h.", "d": "Pleurodese imediata com nitrato de prata para selar o ducto torácico.", "e": "Antibioticoterapia profilática visando estafilococos da pele."}, "answer": "b", "rationale": "O manejo inicial do quilotórax pós-operatório é conservador na maioria dos casos. Envolve a redução da produção de linfa através de dieta com TCM (que é absorvido diretamente pelo sistema porta, saltando o ducto torácico) ou jejum total com Nutrição Parenteral Prolongada (NPP). O octreotide pode ser usado para reduzir as secreções esplâncnicas.", "option_rationales": {"a": "Incorreta. A dieta deve ser pobre em TCL, pois estes estimulam o fluxo linfático.", "b": "Correta. Dieta com TCM e octreotide são os pilares do tratamento clínico inicial.", "c": "Incorreta. A cirurgia é reservada para casos que falham ao tratamento clínico após 1-2 semanas.", "d": "Incorreta. Pleurodese não é o tratamento inicial para quilotórax em crianças.", "e": "Incorreta. O quilo é estéril e possui propriedades bacteriostáticas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax", "Pós-operatório"]}'::jsonb, 6, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Diferenciar um exsudato de um transudato é o passo fundamental na abordagem do derrame pleural. No entanto, os Critérios de Light podem classificar erroneamente até 25% dos transudatos como exsudatos. No caso de suspeita de falso-exsudato, qual dos seguintes parâmetros deve ser solicitado para auxiliar na diferenciação?", "options": {"a": "Gradiente de LDH Soro-Pleura maior que 200 U/L.", "b": "Colesterol pleural < 45 mg/dL.", "c": "Gradiente de Proteína Total (Soro - Pleura) > 3,1 g/dL.", "d": "Densidade do líquido pleural < 1015.", "e": "Bilirrubina pleural / Bilirrubina sérica < 0,5."}, "answer": "c", "rationale": "Quando os critérios de Light sugerem um exsudato, mas a clínica aponta fortemente para ICC ou Cirrose, usamos os gradientes. Um gradiente de Proteína Total (Soro - Pleura) maior que 3,1 g/dL ou um gradiente de Albumina maior que 1,2 g/dL favorecem o diagnóstico de transudato, mesmo com critérios de Light positivos.", "option_rationales": {"a": "Incorreta. Não existe um critério amplamente validado de gradiente de LDH soro-pleura para isso.", "b": "Incorreta. Colesterol pleural > 45 mg/dL é um critério para exsudato, não transudato.", "c": "Correta. O gradiente de proteína > 3,1 g/dL indica transudato em casos de falso-exsudato pelo Light.", "d": "Incorreta. A densidade é um parâmetro antigo e pouco preciso.", "e": "Incorreta. A relação de bilirrubina é um critério adicional para exsudato (se > 0,6), mas menos usado."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Pleural", "Critérios de Light", "Transudato"]}'::jsonb, 7, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente com diagnóstico de Artrite Reumatoide em atividade grave apresenta derrame pleural bilateral. Durante a análise do líquido pleural, observa-se glicose de 10 mg/dL e LDH de 1800 U/L. Assinale a alternativa que apresenta a característica citológica e laboratorial adicional que reforçaria esse diagnóstico específico.", "options": {"a": "Presença de células LE (Lúpus Eritematoso) no líquido.", "b": "Complemento (C3, C4) elevado no líquido pleural.", "c": "Baixos níveis de Fator Reumatoide (FR) no líquido em relação ao soro.", "d": "pH do líquido pleural extremamente baixo, frequentemente < 7,00.", "e": "Presença de eosinófilos > 40% indicando hipersensibilidade."}, "answer": "d", "rationale": "O derrame pleural da Artrite Reumatoide é característico por ser ''explosivo'' do ponto de vista inflamatório: glicose extremamente baixa (muitas vezes < 20 mg/dL), LDH muito alto (> 700 ou 1000) e pH muito baixo. Outros achados incluem FR elevado no líquido e presença de células multinucleadas.", "option_rationales": {"a": "Incorreta. Células LE são características do Lúpus, não da AR.", "b": "Incorreta. O complemento costuma estar reduzido no derrame da AR devido ao consumo.", "c": "Incorreta. O Fator Reumatoide costuma estar elevado no líquido pleural da AR.", "d": "Correta. O pH baixo e a glicose consumida são marcas registradas do derrame da Artrite Reumatoide.", "e": "Incorreta. Eosinofilia pleural não é típica da AR (sugere ar ou sangue na pleura)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Derrame Pleural", "Artrite Reumatoide"]}'::jsonb, 8, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal indicação absoluta para a realização de biópsia pleural por agulha (como a agulha de Cope ou Abrams) em pacientes com derrame pleural exsudativo?", "options": {"a": "Derrame neoplásico já confirmado por citologia para estadiamento.", "b": "Derrame parapneumônico que não responde ao antibiótico inicial.", "c": "Suspeita de Tuberculose Pleural quandoADA é inconclusivo ou em locais de baixa incidência.", "d": "Derrame pleural hemorrágico pós-traumático.", "e": "Avaliação de espessamento pleural no mesotelioma."}, "answer": "c", "rationale": "A biópsia pleural por agulha tem sua maior utilidade na investigação de Tuberculose Pleural, onde o rendimento da análise histopatológica + cultura do fragmento é superior à citologia e cultura do líquido isoladamente. Para neoplasias, a VATS (biópsia dirigida) é preferível se a citologia for negativa.", "option_rationales": {"a": "Incorreta. Se a citologia já confirmou, a biópsia cega não acrescenta muito ao estadiamento.", "b": "Incorreta. Biópsia não é indicada em processos infecciosos agudos piogênicos.", "c": "Correta. A biópsia pleural é o exame de escolha para confirmar TB pleural (visualização do granuloma).", "d": "Incorreta. O trauma exige drenagem ou VATS, não biópsia por agulha cega.", "e": "Incorreta. No mesotelioma, a biópsia cega tem baixo rendimento, sendo indicada a biópsia por videotoracoscopia."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose Pleural", "Biópsia", "Procedimentos"]}'::jsonb, 9, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A toracentese deve ser evitada ou postergada em qual das seguintes condições clínicas, devido ao risco aumentado de complicações hemorrágicas severas?", "options": {"a": "Nível de Creatinina sérica > 6,0 mg/dL (Insuficiência Renal Crônica).", "b": "Uso de Aspirina 100mg/dia (Antiagregante plaquetário).", "c": "Contagem de plaquetas < 50.000/mm³ ou INR > 2,0.", "d": "Presença de ventilação mecânica com PEEP de 10 cmH2O.", "e": "Derrame pleural loculado evidenciado por ultrassom."}, "answer": "c", "rationale": "Embora a toracentese seja um procedimento seguro, contagens de plaquetas abaixo de 50.000 ou coagulopatias severas (INR > 2) aumentam o risco de hemotórax iatrogênico. Nessas condições, as diretrizes sugerem corrigir os níveis antes do procedimento ou realizar com auxílio de ultrassom e extrema cautela.", "option_rationales": {"a": "Incorreta. A uremia afeta a função plaquetária, mas não é contraindicação absoluta por si só.", "b": "Incorreta. O uso de aspirina isolada não exige suspensão para toracentese diagnóstica.", "c": "Correta. Plaquetopenia e INR elevado são marcos de risco hemorrágico elevado.", "d": "Incorreta. Ventilação mecânica exige cuidado, mas não é contraindicação; o US ajuda a evitar pneumotórax.", "e": "Incorreta. O derrame loculado é justamente um alvo para toracentese guiada por imagem."}, "difficulty": "dificil", "tags": ["Pneumologia", "Toracentese", "Segurança do Paciente", "Hematologia"]}'::jsonb, 10, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita com citologia oncótica demonstrando adenocarcinoma de pulmão. É realizada pleurodese química com talco via dreno de tórax. Dez horas após o procedimento, o paciente desenvolve hipoxemia severa, infiltrado pulmonar bilateral difuso ao RX (SDRA) e instabilidade hemodinâmica. Qual a causa mais provável dessa complicação?", "options": {"a": "Embolia pulmonar por fragmentos de tumor.", "b": "Edema pulmonar de reexpansão (EPR).", "c": "Reação inflamatória sistêmica ao talco (Síndrome de Resposta Inflamatória Sistêmica).", "d": "Pneumotórax hipertensivo oculto.", "e": "Infarto agudo do miocárdio tipo 2."}, "answer": "c", "rationale": "A instilação de talco na pleura pode, raramente, causar uma reação inflamatória severa levando à SDRA (Síndrome do Desconforto Respiratório Agudo). Isso está associado especialmente ao uso de ''talco não graduado'' (com partículas muito pequenas que entram na circulação sistêmica) ou doses elevadas.", "option_rationales": {"a": "Incorreta. A embolia tumoral não costuma ser desencadeada pela pleurodese de forma tão aguda.", "b": "Incorreta. O edama de reexpansão ocorre logo após a drenagem volumosa, não 10h após a pleurodese.", "c": "Correta. É uma complicação rara e grave da pleurodese com talco.", "d": "Incorreta. O dreno de tórax está no lugar, o que torna o pneumotórax menos provável como causa primária de SDRA.", "e": "Incorreta. Embora possível em idosos, o quadro relatado é clássico de complicação do talco."}, "difficulty": "dificil", "tags": ["Pneumologia", "Pleurodese", "Complicações", "Oncologia"]}'::jsonb, 11, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o derrame pleural neutrofílico (predomínio de polimorfonucleares > 50%), qual das seguintes afirmações sobre o raciocínio diagnóstico está correta?", "options": {"a": "É característico da fase crônica da Tuberculose Pleural.", "b": "Sempre indica a necessidade de drenagem pleural por tubo.", "c": "Sugere processos agudos na pleura, como pneumonia, embolia pulmonar ou fase muito inicial da tuberculose.", "d": "Descarta a possibilidade de neoplasia maligna primária.", "e": "Indica obrigatoriamente que o líquido é um transudato."}, "answer": "c", "rationale": "A neutrofilia pleural é um sinal de inflamação aguda. As causas mais comuns são o derrame parapneumônico e a embolia pulmonar. Na tuberculose, os polimorfonucleares aparecem apenas nas primeiras 12-48 horas, sendo rapidamente substituídos por linfócitos.", "option_rationales": {"a": "Incorreta. A TB crônica é linfocítica.", "b": "Incorreta. O derrame parapneumônico simples não exige drenagem, apenas o antibiótico.", "c": "Correta. Reflete o estágio inflamatório agudo da pleura.", "d": "Incorreta. Algumas neoplasias agressivas ou com infecção secundária podem cursar com neutrófilos.", "e": "Incorreta. Neutrofilia é típica de exsudatos."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica Líquido Pleural", "Diagnóstico Diferencial"]}'::jsonb, 12, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com Derrame Parapneumônico Complicado onde o dreno tubular não está esvaziando a coleção devido à presença de múltiplas loculações e septações finas, a próxima intervenção recomendada antes de se considerar cirurgia agressiva (decorticação) é:", "options": {"a": "Instilação intrapleural de fibrinolíticos (ex: Estreptoquinase ou tPA/DNase).", "b": "Aumento do calibre do dreno de tórax para 36 French.", "c": "Uso de corticoides sistêmicos (Prednisona) para diminuir a fibrose.", "d": "Realização de pleurodese imediata para ''selar'' as loculações.", "e": "Manter conduta expectante com antibiótico por mais 14 dias."}, "answer": "a", "rationale": "A terapia fibrinolítica intrapleural (frequentemente tPA associado à DNase) pode ajudar a ''quebrar'' as septações de fibrina, facilitando a drenagem e evitando a necessidade de intervenção cirúrgica (VATS ou toracotomia) em até 30-50% dos casos selecionados.", "option_rationales": {"a": "Correta. Fibrinolíticos são indicados para derrames loculados na fase fibrinopurulenta.", "b": "Incorreta. Calibres maiores não atravessam as septações finas do líquido loculado.", "c": "Incorreta. Corticoides não têm papel estabelecido no tratamento do empiema loculado agudo.", "d": "Incorreta. Pleurodese em infecção ativa é um erro grave.", "e": "Incorreta. A loculação impede a cura apenas com antibiótico, levando à organização do empiema."}, "difficulty": "dificil", "tags": ["Pneumologia", "Empiema", "Fibrinolíticos", "Manejo Terapêutico"]}'::jsonb, 13, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 30 anos, HIV positivo, apresenta febre, perda ponderal e derrame pleural linfocítico (90% linfócitos). O ADA é de 35 U/L (valor de corte local = 40 U/L). A biópsia pleural por agulha revela inflamação crônica inespecífica, sem granulomas ou BAAR. Qual a conduta mais racional diante desse quadro inconclusivo?", "options": {"a": "Encaminhar para Videotoracoscopia (VATS) para biópsia dirigida.", "b": "Descartar Tuberculose e investigar Linfoma Pleural.", "c": "Iniciar o tratamento empírico para Tuberculose Pleural.", "d": "Solicitar TRM-TB (Teste Rápido Molecular) e cultura para micobactérias no líquido pleural.", "e": "Repetir a biópsia pleural por agulha de Abrams em outro sítio."}, "answer": "d", "rationale": "Em pacientes com HIV, a apresentação da TB pleural pode ser atípica (ADA mais baixo) e o rendimento da biópsia cega é menor. Antes de procedimentos invasivos como VATS, deve-se esgotar a investigação microbiológica (cultura em meio líquido e teste rápido molecular), que no HIV tem rendimento superior ao esperado na população imunocompetente.", "option_rationales": {"a": "Incorreta. A VATS é o próximo passo se a microbiologia falhar, mas é mais invasiva.", "b": "Incorreta. A TB ainda é o principal suspeito, mesmo com ADA levemente baixo no HIV.", "c": "Incorreta. O tratamento empírico deve ser reservado para quando os exames microbiológicos falham.", "d": "Correta. Cultura e TRM-TB são mandatórios para aumentar a sensibilidade no paciente HIV.", "e": "Incorreta. Repetir biópsia cega não costuma elevar muito o rendimento após a primeira negativa."}, "difficulty": "dificil", "tags": ["Pneumologia", "HIV", "Tuberculose Pleural", "Diagnóstico"]}'::jsonb, 14, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A pseudotumefação pleural (''Tumor Evanescente'' ou ''Tumor Fantasma'') é uma imagem radiológica que pode mimetizar um nódulo ou massa pulmonar sólida. Sobre esta condição, assinale a alternativa que descreve sua localização e etiologia clássicas.", "options": {"a": "Localizada no ápice pulmonar; etiologia associada à Tuberculose.", "b": "Localizada no ângulo costofrênico posterior; etiologia associada à Neoplasia de Cólon.", "c": "Localizada na cisura horizontal ou oblíqua; etiologia associada à Insuficiência Cardíaca Congestiva.", "d": "Localizada no mediastino superior; etiologia associada ao Bócio Mergulhante.", "e": "Localizada na pleura visceral do lobo inferior; etiologia associada ao Infarto Pulmonar."}, "answer": "c", "rationale": "O tumor fantasma é um derrame pleural loculado dentro de uma cisura (geralmente a horizontal), que assume aspecto de massa ao RX. Ele é típico da ICC e ''desaparece'' rapidamente após o início de terapia diurética agressiva, daí o nome.", "option_rationales": {"a": "Incorreta. O tumor fantasma não é apical nem tipicamente da TB.", "b": "Incorreta. A localização clássica é cisural.", "c": "Correta. Localização cisural + ICC é o quadro clínico-radiológico clássico.", "d": "Incorreta. Bócio é uma massa mediastinal, não pleural cisural.", "e": "Incorreta. Infarto pulmonar causa a ''Corcova de Hampton'' (imagem periférica em cunha)."}, "difficulty": "dificil", "tags": ["Pneumologia", "Radiologia", "ICC", "Derrame Loculado"]}'::jsonb, 15, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Considerando o Derrame Pleural Eosinofílico (Eosinófilos > 10% no líquido), qual das seguintes condições é considerada uma causa ''falsa'' ou secundária frequente por introdução de ar ou sangue no espaço pleural?", "options": {"a": "Pneumonia por Chlamydia psittaci.", "b": "Toracocentese prévia ou pneumotórax.", "c": "Infestação por Strongyloides stercoralis.", "d": "Síndrome de Churg-Strauss (Granulomatose Eosinofílica com Poliangiite).", "e": "Sarcoidose em fase pulmonar avançada."}, "answer": "b", "rationale": "A causa mais comum de eosinofilia pleural é a presença de ar (pneumotórax) ou sangue (hemotórax) no espaço pleural. Uma toracentese traumática ou prévia pode induzir eosinofilia reativa em procedimentos subsequentes, o que diminui o valor diagnóstico da eosinofilia para condições raras.", "option_rationales": {"a": "Incorreta. Causas infecciosas bacterianas raramente dão eosinofilia.", "b": "Correta. Ar e sangue são os principais estimulantes de eosinófilos na pleura.", "c": "Incorreta. Parasitoses dão eosinofilia, mas são causas menos comuns que a iatrogenia.", "d": "Incorreta. É uma causa real de eosinofilia pleural, mas muito rara comparada ao trauma/ar.", "e": "Incorreta. Sarcoidose cursa com derrame linfocítico ou granulomatoso."}, "difficulty": "dificil", "tags": ["Pneumologia", "Derrame Eosinofílico", "Etiologia"]}'::jsonb, 16, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de NT-proBNP no líquido pleural pode ser útil em situações específicas de diagnóstico desafiador. Qual o principal cenário onde este exame é recomendado?", "options": {"a": "Confirmar Tuberculose Pleural em pacientes anérgicos.", "b": "Distinguir Transudato Cardíaco de Exsudato Maligno quando os critérios de Light são ambíguos.", "c": "Prever a resposta à pleurodese no câncer de pulmão.", "d": "Identificar pancreatite necrotizante precoce.", "e": "Monitorar a eficácia da antibioticoterapia no empiema."}, "answer": "b", "rationale": "O NT-proBNP pleural (> 1500 pg/mL) é um excelente marcador de insuficiência cardíaca. Ele é útil exatamente quando os critérios de Light classificam o derrame como exsudato (falso-positivo), ajudando a evitar investigações invasivas desnecessárias para câncer ou TB em pacientes com disfunção miocárdica.", "option_rationales": {"a": "Incorreta. NT-proBNP não tem relação com infecções granulomatosas.", "b": "Correta. Auxilia na diferenciação entre causa cardíaca e outras causas em casos borderline.", "c": "Incorreta. Não é marcador prognóstico de pleurodese.", "d": "Incorreta. Para pâncreas usamos amilase e lipase.", "e": "Incorreta. Não é marcador de infecção ou resposta inflamatória aguda bacteriana."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cardiologia", "Biomarcadores", "ICC"]}'::jsonb, 17, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciated": "Paciente masculino, 55 anos, em investigação de ascite e derrame pleural esquerdo volumoso. A análise do líquido pleural mostra: Exsudato, TG = 500 mg/dL, aspecto leitoso. Radiografia mostra espessamento de linfonodos cervicais e retroperitoneais. Qual a patologia mais provável que une esses achados?", "options": {"a": "Cirrose alcoólica Child-Pugh C.", "b": "Linfoma não-Hodgkin.", "c": "Pneumonia pneumocócica com empiema.", "d": "Sarcoidose multissistêmica.", "e": "Mesotelioma pleural maligno."}, "answer": "b", "rationale": "O achado de triglicerídeos > 110 mg/dL e aspecto leitoso confirma Quilotórax. Em adultos, a causa não-traumática mais comum de quilotórax é a obstrução do ducto torácico por neoplasia, sendo o Linfoma a etiologia predominante. A presença de linfonodomegalia cervicorretroperitoneal reforça fortemente essa hipótese.", "option_rationales": {"a": "Incorreta. Cirrose dá transudato e raramente quilotórax (apenas se houver fístula de linfa).", "b": "Correta. Linfoma é a causa principal de quilotórax não-traumático no adulto.", "c": "Incorreta. Empiema é purulento (leucócitos), não quiloso (gordura).", "d": "Incorreta. Sarcoidose raramente causa quilotórax.", "e": "Incorreta. Mesotelioma causa derrame neoplásico citológico ou hemorrágico, raramente quiloso."}, "difficulty": "dificil", "tags": ["Pneumologia", "Linfoma", "Quilotórax", "Hematologia"]}'::jsonb, 18, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a análise citológica do líquido pleural, a presença de uma grande quantidade de células mesoteliais (> 5%) em um exsudato linfocítico fala FORTEMENTE CONTRA qual diagnóstico?", "options": {"a": "Derrame Pleural por Mesotelioma.", "b": "Derrame Pleural por Tuberculose.", "c": "Derrame Pleural por Adenocarcinoma.", "d": "Derrame Pleural por LES.", "e": "Derrame Pleural por Artrite Reumatoide."}, "answer": "b", "rationale": "A Tuberculose Pleural é conhecida por causar uma intensa reação fibrinosa que ''reveste'' a pleura, impedindo a descamação de células mesoteliais para o líquido pleural. Portanto, encontrar muitas células mesoteliais no líquido pleural torna o diagnóstico de TB pleural extremamente improvável.", "option_rationales": {"a": "Incorreta. O mesotelioma, por definição, tem células mesoteliais (malignas).", "b": "Correta. A ausência de células mesoteliais é um dado sugestivo (mas não patognomônico) de TB.", "c": "Incorreta. Neoplasias podem cursar com células mesoteliais normais descamadas.", "d": "Incorreta. O Lúpus não inibe a descamação mesotelial da mesma forma que a TB.", "e": "Incorreta. Na AR a pleura pode estar espessada, mas não há essa exclusão clássica como na TB."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose Pleural", "Citologia", "Mesoteliais"]}'::jsonb, 19, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um homem de 58 anos, com diagnóstico prévio de Linfoma de Hodgkin em remissão após quimioterapia e radioterapia mediastinal há 5 anos, apresenta-se com dispneia aos esforços e tosse seca. A tomografia de tórax revela espessamento pleural difuso e derrame pleural loculado à direita. A análise do líquido pleural mostra exsudato linfocítico, com glicose de 45 mg/dL e LDH de 550 U/L. A citologia oncótica e a cultura são negativas. A biópsia pleural por videotoracoscopia revela fibrose densa com hialinização, sem sinais de malignidade. Qual a causa mais provável para este derrame?", "options": {"a": "Recidiva do linfoma de Hodgkin na pleura.", "b": "Pneumonite por radiação com extensão pleural tardia.", "c": "Mesotelioma maligno induzido por radioterapia prévia.", "d": "Derrame pleural por toxicidade tardia à bleomicina.", "e": "Pleura ''encarcerada'' secundária à radioterapia (fibrose pleural actínica)."}, "answer": "e", "rationale": "A radioterapia mediastinal para o tratamento de linfomas pode causar fibrose pleural e pericárdica tardia, levando ao quadro de pulmão encarcerado ou derrames exsudativos puramente fibróticos (pleura actínica). O achado histopatológico de hialinização e fibrose densa sem células malignas, anos após o tratamento, é característico dessa condição.", "option_rationales": {"a": "Incorreta. A biópsia negativa e o tempo de remissão tornam a recidiva menos provável que a complicação fibrótica.", "b": "Incorreta. A pneumonite actínica costuma ocorrer nos primeiros meses após a radioterapia, não após 5 anos.", "c": "Incorreta. Embora o mesotelioma possa ser induzido por radiação, o achado de fibrose hialina na biópsia aponta para uma causa benigna (cicatricial).", "d": "Incorreta. A toxicidade pela bleomicina geralmente se manifesta como fibrose pulmonar intersticial, não como derrame pleural isolado e espessamento hialino.", "e": "Correta. A fibrose pleural actínica é uma complicação tardia bem descrita da radioterapia torácica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Radioterapia", "Fibrose Pleural", "Derrame Pleural"]}'::jsonb, 20, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente feminina, 42 anos, com história de asma grave e rinossinusite crônica, procura atendimento por dispneia, febre e dor torácica pleurítica à direita. O hemograma revela leucocitose com 22% de eosinófilos (2.500/mm³). A toracentese revela um exsudato com 45% de eosinófilos e pH de 7,30. Diante do quadro sistêmico e pleural, qual o diagnóstico mais provável?", "options": {"a": "Pneumonia por Strongyloides stercoralis com derrame reativo.", "b": "Síndrome de Löffler clássica.", "c": "Granulomatose eosinofílica com poliangiite (Síndrome de Churg-Strauss).", "d": "Derrame pleural induzido pelo uso de montelucaste.", "e": "Infarto pulmonar hemorrágico por tromboembolismo."}, "answer": "c", "rationale": "A Síndrome de Churg-Strauss (GEPA) é caracterizada pelo binômio asma grave + eosinofilia periférica marcada (> 1.500/mm³). O envolvimento pleural ocorre em cerca de 30% dos casos, tipicamente como um exsudato eosinofílico. O quadro de sinusite crônica e asma reforça FORTEMENTE este diagnóstico imuno-reumatológico.", "option_rationales": {"a": "Incorreta. Parasitoses podem dar eosinofilia, mas o quadro clínico de asma grave e sinusite aponta para vasculite.", "b": "Incorreta. A síndrome de Löffler é uma pneumonia eosinofílica autolimitada e migratória, raramente causando derrame pleural importante ou sinusite.", "c": "Correta. A tríade asma + eosinofilia + serosite (derrame) é clássica da GEPA.", "d": "Incorreta. Embora o montelucaste tenha sido associado ao surgimento de Churg-Strauss, a doença é a vasculite em si, não um efeito tóxico direto do remédio na pleura.", "e": "Incorreta. O TEP pode dar eosinofilia pleural leve, mas não explica a eosinofilia periférica grave e a asma/sinusite."}, "difficulty": "dificil", "tags": ["Pneumologia", "Vasculites", "Eosinofilia Pleural", "Churg-Strauss"]}'::jsonb, 21, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Durante uma toracoscopia diagnóstica em um paciente com derrame pleural exsudativo linfocítico unilateral, o cirurgião observa múltiplos pequenos nódulos esbranquiçados espalhados pelas superfícies pleural parietal e visceral, com aspecto de ''grãos de milheto''. Esse achado macroscópico é altamente sugestivo de:", "options": {"a": "Carcinomatose pleural de origem ovariana.", "b": "Mesotelioma maligno em estágio inicial.", "c": "Tuberculose Pleural (forma miliar).", "d": "Sarcoidose de acometimento pleural.", "e": "Talcose pleural iatrogênica."}, "answer": "c", "rationale": "A visualização de ''grânulos'' ou ''grãos de milho'' na superfície pleural durante a VATS é a marca macroscópica da tuberculose pleural. A biópsia desses nódulos confirmará o diagnóstico através da presença de granulomas com necrose de caseificação.", "option_rationales": {"a": "Incorreta. A carcinomatose costuma apresentar nódulos maiores, irregulares e muitas vezes com implantes umbilicados.", "b": "Incorreta. O mesotelioma costuma apresentar espessamento pleural difuso ou massas maiores, não pequenos grânulos uniformes.", "c": "Correta. É o achado clássico da TB pleural na toracoscopia.", "d": "Incorreta. A sarcoidose pleural é rara; embora granulomatosa, a apresentação miliar macroscópica na pleura é excepcional.", "e": "Incorreta. A talcose ocorre após pleurodese e as partículas de talco são irregulares e frequentemente encapsuladas por fibrina mais densa."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Toracoscopia", "Semiologia Pleural"]}'::jsonb, 22, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos apresenta um derrame pleural volumoso recorrente. A análise do líquido revela: Exsudato linfocítico (95%), Glicose 80 mg/dL, ADA 22 U/L, Citologia oncótica negativa. O paciente apresenta também ascite e linfedema de membros inferiores de surgimento espontâneo. Observa-se que as unhas das mãos estão espessas, opacas e com coloração amarelada. Qual a tríade diagnóstica?", "options": {"a": "Síndrome de Meigs.", "b": "Síndrome das Unhas Amarelas.", "c": "Doença de Whipple.", "d": "Linfangioleiomiomatose (LAM).", "e": "Hipotireoidismo severo (Mixedema)."}, "answer": "b", "rationale": "A Síndrome das Unhas Amarelas (Yellow Nail Syndrome) é uma condição rara caracterizada por: 1) Unhas amareladas e distróficas; 2) Linfedema; e 3) Derrame pleural exsudativo (geralmente linfocítico devido à disfunção linfática). A ascite também pode ocorrer como parte da linfedema sistêmico.", "option_rationales": {"a": "Incorreta. A Síndrome de Meigs é a associação de tumor de ovário benigno + ascite + derrame pleural.", "b": "Correta. A descrição das unhas combinada com linfedema e derrame é patognomônica.", "c": "Incorreta. Whipple causa diarreia, perda de peso e dor articular, podendo causar serosite, mas não unhas amarelas.", "d": "Incorreta. A LAM ocorre em mulheres em idade fértil e causa pneumotórax e quilotórax, não a distrofia ungueal descrita.", "e": "Incorreta. O mixedema causa transudatos e não se associa a distrofia ungueal amarelada isolada."}, "difficulty": "dificil", "tags": ["Pneumologia", "Dermatologia", "Derrame Pleural", "Síndromes Raras"]}'::jsonb, 23, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em relação ao diagnóstico diferencial do derrame pleural com baixos níveis de glicose (< 60 mg/dL), qual das seguintes condições costuma apresentar os níveis MAIS BAIXOS de glicose (frequentemente próximos de zero)?", "options": {"a": "Tuberculose Pleural.", "b": "Derrame Pleural Maligno.", "c": "Derrame Pleural por Artrite Reumatoide.", "d": "Derrame Parapneumônico Simples.", "e": "Lúpus Eritematoso Sistêmico."}, "answer": "c", "rationale": "A Artrite Reumatoide (AR) é a condição que produz a maior queda de glicose no líquido pleural, muitas vezes atingindo valores indetectáveis (0 a 10 mg/dL). O mecanismo envolve um bloqueio no transporte de glicose através da pleura inflamada e espessada.", "option_rationales": {"a": "Incorreta. Na TB, a glicose é baixa, mas costuma variar entre 40-60 mg/dL.", "b": "Incorreta. No câncer, a glicose baixa é sinal de grande carga tumoral, variando geralmente entre 30-50 mg/dL.", "c": "Correta. AR e Empiema organizado são as causas de glicose ''zero'' ou quase zero.", "d": "Incorreta. No derrame simples a glicose costuma ser normal.", "e": "Incorreta. No LES a glicose costuma ser normal ou levemente reduzida, raramente tão baixa quanto na AR."}, "difficulty": "dificil", "tags": ["Pneumologia", "Líquido Pleural", "Bioquímica", "Artrite Reumatoide"]}'::jsonb, 24, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 40 anos é admitido com hemotórax traumático após acidente automobilístico. O dreno de tórax é inserido em 5º espaço intercostal, com saída imediata de 1.200 mL de sangue. Nas 2 horas seguintes, a drenagem mantém-se constante em 250 mL/h. O paciente apresenta-se taquicárdico e hipotenso apesar de reposição volêmica. Qual a conduta cirúrgica imediata?", "options": {"a": "Manter observação e drenagem, aguardando 12h para estabilização.", "b": "Realizar videotoracoscopia (VATS) para identificação do sangramento.", "c": "Encaminhar para toracotomia de urgência.", "d": "Realizar arteriografia com embolização das artérias intercostais.", "e": "Administrar ácido tranexâmico e complexo protrombínico imediatamente."}, "answer": "c", "rationale": "As indicações clássicas para toracotomia de urgência no hemotórax traumático incluem: 1) Drenagem imediata > 1.500 mL (ou > 20 mL/kg); ou 2) Drenagem mantida > 200 mL/h nas primeiras 2 a 4 horas; ou 3) Instabilidade hemodinâmica sem outra causa. Este paciente preenche o critério de débito mantido e instabilidade hemodinâmica.", "option_rationales": {"a": "Incorreta. O atraso na intervenção em um quadro de sangramento ativo instável é fatal.", "b": "Incorreta. A VATS é útil no trauma estável ou tardio (hemotórax retido), não no sangramento exsanguinante ativo.", "c": "Correta. Toracotomia de emergência está indicada pelo débito mantido elevado e choque.", "d": "Incorreta. A arteriografia pode ser útil em traumas pélvicos, mas no tórax com sangramento desse volume, a cirurgia é a prioridade.", "e": "Incorreta. São medidas auxiliares, mas não substituem o controle cirúrgico do sangramento massivo."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Hemotórax", "Indicações de Toracotomia"]}'::jsonb, 25, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de NT-proBNP no líquido pleural é útil na diferenciação entre transudatos e exsudatos em contextos ambíguos. No entanto, qual a faixa de valor de corte (cut-off) comumente aceita no líquido pleural para sugerir etiologia de insuficiência cardíaca?", "options": {"a": "> 200 pg/mL", "b": "> 500 pg/mL", "c": "> 1.500 pg/mL", "d": "> 10.000 pg/mL", "e": "> 100 pg/mL"}, "answer": "c", "rationale": "O valor de corte de 1.500 pg/mL para o NT-proBNP no líquido pleural tem alta sensibilidade e especificidade (próximas de 90%) para o diagnóstico de derrame decorrente de insuficiência cardíaca congestiva. Valores abaixo disso em líquidos ambíguos favorecem o diagnóstico de exsudato.", "option_rationales": {"a": "Incorreta. Valor baixo demais, não específico.", "b": "Incorreta. Abaixo do ponto de corte validado na literatura principal.", "c": "Correta. 1.500 pg/mL é o valor clássico de referência diagnóstica.", "d": "Incorreta. Valor exageradamente alto, embora possível em IC grave, o corte é menor.", "e": "Incorreta. Valor de transudato cardíaco é significativamente mais alto."}, "difficulty": "dificil", "tags": ["Pneumologia", "Biomarcadores", "ICC", "NT-proBNP"]}'::jsonb, 26, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 25 anos apresenta quadro de febre, tosse produtiva e derrame pleural à esquerda. A toracentese revela líquido purulento e espesso. A ultrassonografia mostra a pleura visceral ''balançando'' em sincronia com os batimentos cardíacos, sinal conhecido como ''Sinal do Pulso''. Qual o significado clínico deste achado ultrassonográfico?", "options": {"a": "Indica empiema na fase aguda com perfuração pericárdica iminente.", "b": "Sugere atelectasia total do pulmão subjacente (ausência de respiração e presença de transmissão de pulso cardíaco).", "c": "É um sinal clássico de pneumonia necrotizante com fístula broncopleural.", "d": "Indica que o líquido pleural é de baixa densidade (transudato).", "e": "Representa a presença de ar intrapleural (hidropneumotórax)."}, "answer": "b", "rationale": "O ''Static B-lines'' associado ao ''Lung Pulse'' na ultrassonografia pulmonar indica que o pulmão não está ventilando (atelectasia), mas o parênquima ainda está em contato com o mediastino, transmitindo as pulsações cardíacas. No contexto de empiema ou derrame pleural massivo, sugere que o parênquima adjacente está colapsado e não aerado.", "option_rationales": {"a": "Incorreta. Não indica risco de perfuração pericárdica.", "b": "Correta. O sinal do pulso é característico de pulmão consolidado/atelectasiado sem ventilação.", "c": "Incorreta. A fístula broncopleural costuma dar o sinal da ''cauda de cometa'' ou pontos de ar móveis.", "d": "Incorreta. É um achado de parênquima/consolidação, não do líquido em si.", "e": "Incorreta. Ar na pleura (pneumotórax) abole o lung pulse e todas as outras linhas pulmonares pela ausência de contato pleura-pleura."}, "difficulty": "dificil", "tags": ["Pneumologia", "Ultrassonografia", "Semiologia", "Atelectasia"]}'::jsonb, 27, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal complicação iatrogênica associada à toracocentese diagnóstica realizada sem auxílio de ultrassonografia, especialmente em derrames de pequeno volume?", "options": {"a": "Edema pulmonar de reexpansão.", "b": "Pneumoniti por aspiração de líquido pleural.", "c": "Pneumotórax.", "d": "Lipotímia vasovagal.", "e": "Infecção do espaço pleural (Empiema iatrogênico)."}, "answer": "c", "rationale": "O pneumotórax é a complicação iatrogênica mais frequente da toracocentese ''cega''. O uso sistemático da ultrassonografia à beira do leito (POCUS) reduziu essa taxa de aproximadamente 10% para menos de 1-2% na prática clínica moderna.", "option_rationales": {"a": "Incorreta. Isso ocorre apenas após drenagens volumosas (> 1,5L), não em toracocenteses diagnósticas pequenas.", "b": "Incorreta. Aspirar líquido não causa pneumonia por aspiração do próprio líquido na via aérea.", "c": "Correta. A lesão pulmonar pela agulha é o risco principal sem guia de imagem.", "d": "Incorreta. É comum mas benigna, não relacionada à falta de US diretamente.", "e": "Incorreta. Raro se mantida técnica asséptica adequada."}, "difficulty": "facil", "tags": ["Pneumologia", "Procedimentos", "Toracocentese", "Segurança"]}'::jsonb, 28, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Mulher de 35 anos apresenta-se com quadro de endometriose pélvica conhecida. Durante o período menstrual, ela relata episódios recorrentes de dor torácica súbita e dispneia. O último episódio resultou em um derrame pleural hemorrágico à direita. A tomografia mostra pequenos nódulos pleurais e diafragmáticos com sinal de sangue agudo. Qual o diagnóstico?", "options": {"a": "Hemotórax espontâneo por ruptura de fístula arteriovenosa.", "b": "Endometriose Pleural (Hemotórax Catamenial).", "c": "Tuberculose Pleural hemorrágica.", "d": "Câncer de ovário com metástase pleural precoce.", "e": "Linfangioleiomiomatose com hemoptise associada."}, "answer": "b", "rationale": "A endometriose torácica pode causar pneumotórax catamenial (mais comum), hemotórax catamenial ou hemoptise catamenial. A característica principal é a ciclicidade dos sintomas, coincidindo com o período menstrual (geralmente entre 24-48h do início da menstruação). O hemitórax direito é acometido em > 90% dos casos devido à circulação peritoneal rumo aos poros diafragmáticos direitos.", "option_rationales": {"a": "Incorreta. Não explica a ciclicidade menstrual.", "b": "Correta. A ciclicidade e a localização à direita são marcos da endometriose torácica/pleural.", "c": "Incorreta. TB não é cíclica.", "d": "Incorreta. Metástases dariam sintomas constantes e progressivos.", "e": "Incorreta. A LAM causa quilotórax e pneumotórax, não tipicamente hemotórax recorrente cíclico."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Endometriose Torácica", "Hemotórax"]}'::jsonb, 29, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 65 anos, portador de artrite reumatoide há 20 anos, apresenta derrame pleural bilateral de longa data, assintomático. Durante análise do líquido pleural, observa-se a presença de cristais rômbicos no sedimento sob luz polarizada. Este achado é sugestivo de:", "options": {"a": "Gota com acometimento pleural.", "b": "Derrame Pleural por Colesterol (Pseudochylothorax).", "c": "Infecção por fungos filamentosos.", "d": "Contaminação do líquido por talco de luva.", "e": "Artrite reumatoide em fase de remissão completa."}, "answer": "b", "rationale": "O pseudoquilotórax (ou derrame de colesterol) ocorre em derrames pleurais crônicos e espessados (frequentemente causados por AR ou Tuberculose de longa data). O colesterol se acumula no líquido, podendo formar cristais de colesterol típicos no sedimento. O TG costuma ser baixo (< 110 mg/dL), diferenciando do quilotórax verdadeiro.", "option_rationales": {"a": "Incorreta. Gota pleuropulmonar é extremamente rara; os cristais seriam de urato de sódio (agulhas).", "b": "Correta. Os cristais de colesterol são típicos de processos pleurais crônicos (Pseudochylothorax).", "c": "Incorreta. Fungos mostram hifas, não cristais rômbicos.", "d": "Incorreta. Talco de luva tem aspecto de ''cruz de malta'' na luz polarizada.", "e": "Incorreta. O achado indica cronicidade e espessamento da pleura, não remissão da inflamação local."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Colesterol Pleural", "Pseudoquilotórax"]}'::jsonb, 30, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre a Síndrome de Meigs, assinale a alternativa que descreve CORRETAMENTE a condição.", "options": {"a": "Metástase ovariana de câncer gástrico (Tumor de Krukenberg) com derrame maligno.", "b": "Tumor ovariano benigno (geralmente fibroma), ascite e derrame pleural.", "c": "Derrame pleural bilateral associado a lúpus discoide e artrite.", "d": "Ascite volumosa por cirrose que transloca para a pleura esquerda.", "e": "Tumor de pulmão com invasão direta do ovário e peritônio."}, "answer": "b", "rationale": "A Síndrome de Meigs clássica consiste em um tumor ovariano benigno (fibroma, tecoma ou cistoadenoma), ascite e derrame pleural (mais comum à direita). O marco da síndrome é que tanto o derrame quanto a ascite desaparecem permanentemente após a remoção do tumor ovariano.", "option_rationales": {"a": "Incorreta. Meigs exige tumor benigno.", "b": "Correta. Definição clássica da síndrome.", "c": "Incorreta. Não tem relação com o perfil de Meigs.", "d": "Incorreta. Isso seria hidrotórax hepático.", "e": "Incorreta. Meigs é um tumor primário de ovário, não de pulmão."}, "difficulty": "media", "tags": ["Pneumologia", "Ginecologia", "Síndrome de Meigs"]}'::jsonb, 31, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No manejo do derrame pleural neoplásico recorrente, a pleurodese química é uma opção comum. Qual a contraindicação PRINCIPAL para a realização de pleurodese?", "options": {"a": "Volume de derrame superior a 1 litro.", "b": "Presença de atelectasia obstrutiva sem reexpansão pulmonar após drenagem (Pulmão Encarcerado).", "c": "Idade superior a 80 anos.", "d": "Uso de quimioterapia há menos de 7 dias.", "e": "Classificação do líquido como exsudato."}, "answer": "b", "rationale": "Para que a pleurodese funcione, é necessário que as pleuras visceral e parietal entrem em contato após a drenagem para que o agente irritante (talco, nitrato, etc.) promova a sínfise. Se o pulmão estiver ''encarcerado'' (trapped lung) por tumor ou fibrose e não reexpandir, a pleurodese irá falhar invariavelmente.", "option_rationales": {"a": "Incorreta. Volume alto não é contraindicação se o pulmão reexpandir.", "b": "Correta. A ausência de reexpansão garante a falha do procedimento.", "c": "Incorreta. Idade não impede, apenas exige cautela na dose de sedação.", "d": "Incorreta. A quimio não contraindica, embora possa reduzir a resposta inflamatória desejada.", "e": "Incorreta. Quase todos os derrames neoplásicos são exsudatos."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Pleurodese", "Manejo"]}'::jsonb, 32, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual medicação, muito utilizada no tratamento de infecção urinária recorrente, é uma causa clássica e bem conhecida de derrame pleural exsudativo com eosinofilia e infiltrado pulmonar intersticial por mecanismo de hipersensibilidade?", "options": {"a": "Ciprofloxacino.", "b": "Nitrofurantoína.", "c": "Norfloxacino.", "d": "Fosfomicina.", "e": "Ceftriaxona."}, "answer": "b", "rationale": "A nitrofurantoína pode causar toxicidade pulmonar aguda ou crônica. A forma aguda é uma reação de hipersensibilidade caracterizada por febre, calafrios, tosse, eosinofilia periférica e derrame pleural eosinofílico. A suspensão da droga costuma levar à rápida resolução do quadro.", "option_rationales": {"a": "Incorreta. Quinolonas raramente causam tal reação.", "b": "Correta. Causa clássica de toxicidade pleuropulmonar eosinofílica.", "c": "Incorreta. Não associada tipicamente a este quadro.", "d": "Incorreta. Medicação segura do ponto de vista pulmonar.", "e": "Incorreta. Não apresenta este padrão de toxicidade."}, "difficulty": "facil", "tags": ["Pneumologia", "Farmacodinâmica", "Derrame Pleural Iatrogênico", "Nitrofurantoína"]}'::jsonb, 33, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com pneumonia da comunidade que desenvolve derrame pleural associado, qual o achado na análise do líquido pleural que MELHOR prediz a necessidade de drenagem torácica?", "options": {"a": "Presença de linfócitos > 50%.", "b": "ADA > 40 U/L.", "c": "LDH pleural > 1.000 U/L ou pH < 7,2.", "d": "Glicose pleural de 80 mg/dL.", "e": "Volume de derrame superior a 500 mL na radiografia."}, "answer": "c", "rationale": "Os critérios bioquímicos de complicação de um derrame parapneumônico (indicadores de drenagem) são: pH < 7,20, glicose < 40-60 mg/dL, ou LDH > 1.000 U/L. A presença de pus franco ou Gram/cultura positivos também são indicações absolutas.", "option_rationales": {"a": "Incorreta. Sugere TB ou neoplasia, não pneumonia bacteriana aguda.", "b": "Incorreta. Sugere TB.", "c": "Correta. Marcadores bioquímicos de empiema/complicado.", "d": "Incorreta. Glicose normal costuma indicar derrame simples.", "e": "Incorreta. O volume isolado não decide a drenagem, mas sim a composição bioquímica/biológica."}, "difficulty": "media", "tags": ["Pneumologia", "Empiema", "Manejo", "Drenagem"]}'::jsonb, 34, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A fístula quilosa (Quilotórax) pode levar a consequências metabólicas e imunológicas graves se não tratada precocemente. Qual é a principal alteração laboratorial sistêmica esperada em casos de quilotórax volumoso prolongado?", "options": {"a": "Hipernatremia e hipercalemia.", "b": "Linfopenia e Hipogamaglobulinemia.", "c": "Trombocitose reativa.", "d": "Hipercolesterolemia grave.", "e": "Alcalose metabólica hipoclorêmica."}, "answer": "b", "rationale": "A linfa é riquíssima em linfócitos T (principalmente T-helper) e imunoglobulinas. Pacientes com drenagem mantida de quilo perdem essas defesas, desenvolvendo linfopenia sistêmica profunda e redução de IGs séricas, o que aumenta drasticamente o risco de infecções oportunistas.", "option_rationales": {"a": "Incorreta. Perde-se eletrólitos, tendendo a hiponatremia se houver reposição hídrica apenas com água livre, mas não é a marca principal.", "b": "Correta. Consequência direta da perda do fluido linfático rico em imunidade celular e humoral.", "c": "Incorreta. Não há associação direta.", "d": "Incorreta. Os lipídios estão sendo perdidos para fora da circulação sérica, não acumulados.", "e": "Incorreta. Pode haver acidose metabólica pela perda de bicarbonato na linfa."}, "difficulty": "dificil", "tags": ["Pneumologia", "Quilotórax", "Fisiologia", "Imunidade"]}'::jsonb, 35, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 60 anos com quadro de ascite e derrame pleural exsudativo linfocítico unilateral. RX mostra nódulo pulmonar espiculado. Qual a sensibilidade aproximada da citologia oncótica do líquido pleural para o diagnóstico de malignidade em uma primeira amostra bem coletada?", "options": {"a": "Próxima de 100%.", "b": "Entre 80% e 95%.", "c": "Entre 50% e 65%.", "d": "Menos de 20%.", "e": "0%, pois a biópsia é sempre necessária."}, "answer": "c", "rationale": "A sensibilidade da primeira amostra de citologia oncótica gira em torno de 50-60%. Se uma segunda amostra for enviada, a sensibilidade sobe para cerca de 75-80%. Amostras adicionais após a segunda trazem ganho marginal de diagnóstico, sendo indicada a biópsia se a dúvida persistir.", "option_rationales": {"a": "Incorreta. Frequentemente a citologia é falha na primeira amostra.", "b": "Incorreta. Valor alcançado apenas após várias amostras ou em casos específicos de adenocarcinoma avançado.", "c": "Correta. Faixa de sensibilidade clássica da primeira toracentese.", "d": "Incorreta. A citologia é um excelente exame inicial, com rendimento razoável.", "e": "Incorreta. A citologia muitas vezes descarta a necessidade de biópsia invasiva."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Diagnóstico", "Citologia"]}'::jsonb, 36, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente submetido a cirurgia abdominal de grande porte via laparotomia mediana desenvolve febre baixa e pequena quantidade de derrame pleural bilateral no 2º dia pós-operatório. Ele está estável, sem dispneia. RX mostra atelectasias laminares nas bases. Qual a explicação mais provável e a melhor conduta?", "options": {"a": "Pneumonia nosocomial precoce; iniciar meropenem.", "b": "TEP pós-operatório; solicitar Angio-TC de urgência.", "c": "Derrame pleural simpático secundário à cirurgia abdominal e atelectasia; fisioterapia respiratória.", "d": "Empiema por translocação bacteriana; realizar toracentese imediata.", "e": "Quilotórax por lesão inadvertida do ducto torácico; dieta zero."}, "answer": "c", "rationale": "É muito comum a ocorrência de pequenos derrames pleurais no pós-operatório imediato de cirurgias abdominais superiores. Eles ocorrem por irritação diafragmática, manipulação de fluidos ou atelectasias de base. Se o paciente está estável, a conduta é expectante e focada na reexpansão pulmonar com fisioterapia.", "option_rationales": {"a": "Incorreta. Quadro clínico leve demais para pneumonia grave.", "b": "Incorreta. Embora possível, o quadro é muito típico de reação pós-cirúrgica benigna.", "c": "Correta. Derrame reativo comum em cirurgias abdominais.", "d": "Incorreta. Empiema não surge tão rápido e sem foco infectado importante.", "e": "Incorreta. Cirurgia abdominal dificilmente lesa o ducto torácico a ponto de dar derrame bilateral no 2º dia sem outras queixas."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia", "Pós-operatório", "Derrame Reativo"]}'::jsonb, 37, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A dosagem de interferon-gama (IFN-γ) no líquido pleural tem sido estudada como alternativa à dosagem de ADA para o diagnóstico de tuberculose pleural. Em comparação ao ADA, o INF-γ costuma apresentar:", "options": {"a": "Menor sensibilidade e maior custo.", "b": "Maior especificidade, porém custo mais elevado e menor disponibilidade.", "c": "Inutilidade total, sendo inferior em todos os parâmetros.", "d": "Falsos-positivos frequentes em transudatos cardíacos.", "e": "Resultado sempre negativo em pacientes HIV positivos."}, "answer": "b", "rationale": "O interferon-gama pleural tem acurácia diagnóstica excelente para TB, por vezes superior ao ADA em especificidade. No entanto, devido ao alto custo e à complexidade laboratorial, o ADA permanece como o exame de escolha na prática clínica (custo-efisicácia superior).", "option_rationales": {"a": "Incorreta. A sensibilidade também é muito alta.", "b": "Correta. Desempenho excelente, mas custo e acesso são barreiras.", "c": "Incorreta. É um ótimo teste científico.", "d": "Incorreta. Ele é muito específico para inflamação granulomatosa/TB.", "e": "Incorreta. Pode ser positivo no HIV, embora a carga linfocitária possa influenciar o nível absoluto."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Biomarcadores", "IFN-gama"]}'::jsonb, 38, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a principal causa de hemotórax não traumático (espontâneo) em um adulto jovem previamente hígido, sem história de coagulopatia?", "options": {"a": "Ruptura de aneurisma de aorta descendente.", "b": "Perfuração de artéria intercostal por tosse vigorosa.", "c": "Pneumotórax espontâneo primário (ruptura de bridas vasculares pleurais durante o colapso pulmonar).", "d": "Malformação arteriovenosa pulmonar.", "e": "Câncer de pulmão oculto."}, "answer": "c", "rationale": "O hemopneumotórax espontâneo ocorre em cerca de 1-5% dos casos de pneumotórax espontâneo primário. O sangramento ocorre geralmente pela ruptura de pequenas vasos ou bridas que ligam a pleura parietal à visceral durante o colapso do pulmão. Pode ser volumoso e exigir intervenção.", "option_rationales": {"a": "Incorreta. Causa de idosos hipertensos, não jovens hígidos.", "b": "Incorreta. Muito raro sem trauma direto.", "c": "Correta. Mecanismo clássico de hemotórax espontâneo no jovem.", "d": "Incorreta. A MAV pode causar hemoptise ou hemotórax, mas é menos frequente que a complicação do pneumotórax.", "e": "Incorreta. Muito improvável na faixa etária e perfil descrito."}, "difficulty": "media", "tags": ["Pneumologia", "Pneumotórax", "Hemotórax", "Urgências"]}'::jsonb, 39, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 52 anos com Leucemia Mieloide Crônica (LMC) em tratamento com Dasatinibe há 6 meses apresenta-se com dispneia progressiva e tosse seca. A radiografia de tórax revela derrame pleural bilateral volumoso. A toracentese mostra um exsudato linfocítico com citologia oncótica negativa. Após exclusão de infecções e progressão da doença de base, qual a melhor conduta para este paciente?", "options": {"a": "Iniciar quimioterapia de resgate para progressão de LMC.", "b": "Realizar pleurodese imediata com talco.", "c": "Suspensão temporária do Dasatinibe e uso de diuréticos/corticoides conforme necessidade.", "d": "Encaminhar para decorticação pulmonar bilateral.", "e": "Substituir Dasaribe por Hidroxiureia permanentemente."}, "answer": "c", "rationale": "O Dasatinibe, um inibidor de tirosina quinase, é uma causa bem conhecida de derrame pleural (ocorre em até 20-30% dos pacientes). O líquido é classicamente um exsudato linfocítico. A conduta padrão envolve a pausa da medicação ou redução da dose, associada a diuréticos ou cursos curtos de corticoides. O derrame costuma recorrer se a droga for reiniciada na mesma dose.", "option_rationales": {"a": "Incorreta. O derrame é um efeito colateral da droga, não sinal de falha terapêutica da LMC.", "b": "Incorreta. Pleurodese não é tratamento para derrame induzido por droga antes de tentar o manejo medicamentoso.", "c": "Correta. Pausa da droga e suporte clínico é a conduta recomendada.", "d": "Incorreta. Medida invasiva desnecessária para um efeito colateral reversível.", "e": "Incorreta. A substituição pode ser necessária, mas o Dasatinibe é uma droga de ponta; tenta-se o ajuste de dose antes da troca definitiva se possível."}, "difficulty": "dificil", "tags": ["Pneumologia", "Hematologia", "Derrame Iatrogênico", "Dasatinibe"]}'::jsonb, 40, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Glicose no líquido pleural é consumida por processos inflamatórios intensos e atividade metabólica de células malignas ou bactérias. No entanto, qual das seguintes situações apresenta, paradoxalmente, níveis de glicose no líquido pleural EQUIVALENTES aos níveis séricos, mesmo na presença de um exsudato volumoso?", "options": {"a": "Empiema bacteriano organizado.", "b": "Tuberculose Pleural clássica.", "c": "Derrame Pleural por Mesotelioma Maligno.", "d": "Derrame Pleural por Quilotórax (não complicado).", "e": "Artrite Reumatoide em fase aguda."}, "answer": "d", "rationale": "No quilotórax primário ou traumático (sem infecção associada), a barreira pleural não está inflamada a ponto de impedir o transporte de glicose, e não há consumo bacteriano ou tumoral excessivo. Assim, a glicose pleural costuma ser equivalente à sérica, o que ajuda a diferenciar de outros exsudatos linfocíticos inflamatórios como a TB ou Câncer.", "option_rationales": {"a": "Incorreta. Glicose é muito baixa (< 40).", "b": "Incorreta. Glicose costuma estar reduzida (< 60).", "c": "Incorreta. Glicose frequentemente baixa no câncer avançado.", "d": "Correta. O quilo puramente linfático não altera a cinética da glicose.", "e": "Incorreta. A AR é a causa de glicose mais baixa de todas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Bioquímica", "Quilotórax", "Glicose Pleural"]}'::jsonb, 41, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico e com histórico de exposição ocupacional ao asbesto há 30 anos apresenta-se com dor torácica persistente e emagrecimento. A tomografia mostra espessamento pleural nodular e circunferencial envolvendo a pleura parietal e visceral, com invasão do diafragma e gordura mediastinal. O diagnóstico histopatológico revela Mesotelioma Maligno. Qual o subtipo histológico mais comum e de melhor prognóstico?", "options": {"a": "Sarcomatoide.", "b": "Epitelioide.", "c": "Bifásico.", "d": "Desmoplásico.", "e": "Pequenas Células."}, "answer": "b", "rationale": "O mesotelioma epitelioide é a variante histológica mais comum (50-70% dos casos) e apresenta um prognóstico significativamente melhor do que as variantes sarcomatoide ou bifásica. O diagnóstico imuno-histoquímico (Calretinina, WT1) é essencial para distinguir do adenocarcinoma.", "option_rationales": {"a": "Incorreta. Variante agressiva e de pior prognóstico.", "b": "Correta. Mais comum e com sobrevida ligeiramente superior.", "c": "Incorreta. Combina elementos epitelioides e sarcomatoides, prognóstico intermediário.", "d": "Incorreta. Variante rara e geralmente muito agressiva.", "e": "Incorreta. Não é um subtipo clássico do mesotelioma pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Mesotelioma", "Asbesto"]}'::jsonb, 42, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A Síndrome de Doege-Potter é uma síndrome paraneoplásica rara associada a um tumor específico da pleura. Ela se caracteriza por episódios de hipoglicemia grave devido à produção de uma forma anômala de IGF-2 (Insulin-like growth factor 2) pelo tumor. Qual é o tumor pleural caracteristicamente associado a essa síndrome?", "options": {"a": "Mesotelioma Pleural Maligno.", "b": "Tumor Fibroso Solitário da Pleura (TFSP).", "c": "Adenocarcinoma de pulmão invasivo.", "d": "Linfoma Pleural Primário.", "e": "Timoma com implante pleural."}, "answer": "b", "rationale": "O Tumor Fibroso Solitário da Pleura (anteriormente chamado de mesotelioma benigno, embora possa ser maligno) é um tumor mesenquimal que pode cursar com a Síndrome de Doege-Potter. A hipoglicemia ocorre pela secreção de ''big'' IGF-2, que estimula os receptores de insulina.", "option_rationales": {"a": "Incorreta. Mesotelioma não causa hipoglicemia paraneoplásica.", "b": "Correta. Associação clássica da questão de prova de alto nível.", "c": "Incorreta. Adenocarcinoma não produz IGF-2.", "d": "Incorreta. Não associado.", "e": "Incorreta. Timomas podem causar Miastenia Gravis, mas não Doege-Potter."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Síndromes Paraneoplásicas", "TFSP"]}'::jsonb, 43, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente em diálise peritoneal ambulatorial desenvolve dispneia súbita e derrame pleural maciço à direita. Suspeita-se de ''Hidrotórax Doce'' (fístula pleuroperitoneal). Qual o parâmetro laboratorial no líquido pleural que confirma este diagnóstico com maior precisão?", "options": {"a": "Presença de células de descamação pleural (mesoteliais).", "b": "Glicose pleural significativamente MAIOR que a glicose sérica.", "c": "ADA elevado e linfocitose.", "d": "Proteína pleural superior a 3,0 g/dL.", "e": "Presença de cristais de colesterol no líquido."}, "answer": "b", "rationale": "No hidrotórax secundário à diálise peritoneal, o líquido que vaza para a pleura é o próprio dialisado, que possui uma concentração de glicose altíssima. Assim, encontrar glicose pleural muito superior à sérica (ex: 200, 300 mg/dL ou mais) é diagnóstico da fístula pleuroperitoneal.", "option_rationales": {"a": "Incorreta. Não é específico, qualquer derrame ascitogênico pode ter.", "b": "Correta. O termo ''Hidrotórax Doce'' vem justamente da glicose elevada vinda do dialisado.", "c": "Incorreta. Sugere TB e não tem relação com diálise.", "d": "Incorreta. O dialisado é pobre em proteínas (transudato).", "e": "Incorreta. Sugere pseudochylothorax crônico."}, "difficulty": "dificil", "tags": ["Pneumologia", "Nefrologia", "Hidrotórax Doce", "Diálise Peritoneal"]}'::jsonb, 44, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O Urinotórax é uma condição rara onde a urina se acumula no espaço pleural, geralmente por obstrução urinária ou trauma urológico. Qual das alternativas descreve as características bioquímicas típicas desse líquido?", "options": {"a": "Exsudato neutrofílico com pH alcalino (> 8,0).", "b": "Transudato com odor fétido e pH ácido (< 7,0).", "c": "Transudato com relação Creatinina Pleural / Creatinina Sérica > 1,0.", "d": "Exsudato com glicose zero e ADA elevado.", "e": "Líquido de aspecto leitoso rico em amônia."}, "answer": "c", "rationale": "O urinotórax é a única causa de transudato que se apresenta com pH ácido (< 7,30). O diagnóstico é confirmado pela relação creatinina pleural / creatinina sérica > 1,0 (frequentemente > 5,0). O líquido mimetiza a química da urina.", "option_rationales": {"a": "Incorreta. O urinotórax é classicamente um transudato.", "b": "Incorreta. Embora o pH seja ácido, o líquido pode ter odor de urina, não necessariamente ''fétido'' de infecção.", "c": "Correta. A relação de creatinina é o achado confirmatório.", "d": "Incorreta. Características de TB ou artrite reumatoide.", "e": "Incorreta. Aspecto leitoso sugere quilotórax."}, "difficulty": "dificil", "tags": ["Pneumologia", "Urologia", "Urinotórax", "Diagnóstico Diferencial"]}'::jsonb, 45, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A exposição ocupacional ao asbesto (amianto) pode causar várias doenças pleurais benignas. Qual delas é caracterizada por ser unilateral, frequentemente recorrente, assintomática ou associada a dor leve, e que resolve espontaneamente deixando muitas vezes apenas o ângulo costofrênico rombo?", "options": {"a": "Placas Pleurais Parietais.", "b": "Derrame Pleural Benigno do Asbesto (BAPE).", "c": "Atelectasia Redonda.", "d": "Mesotelioma Maligno em fase inicial.", "e": "Asbestose Pulmonar."}, "answer": "b", "rationale": "O BAPE (Benign Asbestos Pleural Effusion) é a manifestação mais precoce da exposição ao asbesto (ocorre nos primeiros 10-20 anos). É um exsudato, muitas vezes hemorrágico ou eosinofílico, que costuma resolver sozinho entre 3 a 4 meses, mas pode recorrer. É um diagnóstico de exclusão.", "option_rationales": {"a": "Incorreta. Placas pleurais são lesões sólidas, fibróticas e calcificadas, não derrames.", "b": "Correta. Quadro clínico clássico de derrame benigno por exposição laboral.", "c": "Incorreta. É uma massa parenquimatosa periférica causada por invaginação da pleura visceral, não é um derrame recorrente.", "d": "Incorreta. O mesotelioma não regride espontaneamente.", "e": "Incorreta. Asbestose é a fibrose do parênquima pulmonar, não da pleura."}, "difficulty": "media", "tags": ["Pneumologia", "Medicina do Trabalho", "Asbesto", "BAPE"]}'::jsonb, 46, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente de 4 anos com quadro de febre alta, dispneia e prostração. Radiografia de tórax mostra derrame pleural à direita ocupando 50% do hemitórax. Realizada toracentese que evidencia líquido turvo com pH de 7,05, glicose de 28 mg/dL e LDH de 2.200 U/L. O patógeno MAIS PROVÁVEL de ser isolado neste empiema pediátrico é:", "options": {"a": "Mycoplasma pneumoniae.", "b": "Streptococcus pneumoniae.", "c": "Staphylococcus aureus.", "d": "Haemophilus influenzae tipo b.", "e": "Klebsiella pneumoniae."}, "answer": "b", "rationale": "O Pneumococo (Streptococcus pneumoniae) continua sendo a causa número 1 de derrame pleural parapneumônico e empiema em crianças, mesmo após a introdução das vacinas conjugadas (devido ao escape de alguns sorotipos).", "option_rationales": {"a": "Incorreta. Mycoplasma raramente causa empiemas purulentos volumosos.", "b": "Correta. Principal etiologia na pediatria.", "c": "Incorreta. O S. aureus é comum e grave, mas o pneumococo ainda lidera as estatísticas gerais.", "d": "Incorreta. Tornou-se raro após a vacinação extensiva.", "e": "Incorreta. Raro em crianças hígidas; mais associado a etilistas e diabéticos adultos."}, "difficulty": "facil", "tags": ["Pneumologia", "Pediatria", "Empiema", "Infectologia"]}'::jsonb, 47, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o Derrame Pleural da Sarcoidose, assinale a correta.", "options": {"a": "Ocorre em mais da metade dos pacientes com sarcoidose estágio II.", "b": "O líquido pleural é tipicamente um exsudato linfocítico com alta relação CD4/CD8.", "c": "É invariavelmente hemorrágico e cursa com glicose zero.", "d": "A presença de derrame pleural exclui o diagnóstico de sarcoidose sistêmica.", "e": "O ADA pleural costuma ser superior a 100 U/L."}, "answer": "b", "rationale": "O derrame pleural na sarcoidose é raro (1-5% dos casos). Quando ocorre, é um exsudato linfocítico. Assim como no lavado broncoalveolar da sarcoidose, o líquido pleural apresenta uma relação entre linfócitos T CD4+ e CD8+ elevada (Geralmente > 3,5).", "option_rationales": {"a": "Incorreta. É uma manifestação incomum.", "b": "Correta. Reflete o padrão de resposta imune Th1 da sarcoidose.", "c": "Incorreta. Não é hemorrágico nem consome glicose de forma acentuada.", "d": "Incorreta. Não exclui, mas obriga a afastar TB e câncer pelo perfil linfocítico.", "e": "Incorreta. O ADA costuma ser baixo ou moderado, não atingindo os níveis da TB."}, "difficulty": "dificil", "tags": ["Pneumologia", "Sarcoidose", "Linfócitos", "CD4/CD8"]}'::jsonb, 48, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A presença de ''pseudocilindros'' ou ''corpúsculos de grãos'' no líquido pleural pode ocorrer em casos de pleurite traumática crônica ou processos degenerativos de longa data. No entanto, o achado de células mesoteliais multinucleadas e gigantes é mais sugestivo de qual condição autoimune?", "options": {"a": "Esclerodermia Sistêmica.", "b": "Lúpus Eritematoso Sistêmica (LES).", "c": "Artrite Reumatoide (AR).", "d": "Dermatomiosite.", "e": "Poliarterite Nodosa."}, "answer": "c", "rationale": "O líquido pleural da Artrite Reumatoide possui achados citológicos peculiares, como a presença de macrófagos gigantes multinucleados e células alongadas (spindle cells), que representam restos de sinovite granulomatosa na pleura.", "option_rationales": {"a": "Incorreta. Esclerodermia causa mais fibrose pulmonar do que derrame exuberante.", "b": "Incorreta. O LES apresenta as ''células LE'' e anticorpos específicos.", "c": "Correta. Citologia característica da pleurite reumatoide.", "d": "Incorreta. Manifestação rara.", "e": "Incorreta. Vasculite de médios vasos, raramente acomete a pleura com este padrão."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Citologia Pleural", "Artrite Reumatoide"]}'::jsonb, 49, 'draft');